stenti</h5>\r\n          @if (isLoadingAssessments) {\r\n            <div class=\"text-center py-3\">\r\n              <div class=\"spinner-border text-primary\" role=\"status\">\r\n                <span class=\"visually-hidden\">Caricamento...</span>\r\n              </div>\r\n            </div>\r\n          } @else {\r\n            <div class=\"table-responsive\">\r\n              <table class=\"table table-hover table-sm mb-0\">\r\n                <thead class=\"table-light\">\r\n                  <tr>\r\n                    <th scope=\"col\">Data</th>\r\n                    <th scope=\"col\">Stato</th>\r\n                    <th scope=\"col\">Versione</th>\r\n                    <th scope=\"col\">Punteggio Totale</th>\r\n                    <th scope=\"col\">Disabilit\u00E0 %</th>\r\n                    <th scope=\"col\" class=\"text-center\">Azioni</th>\r\n                  </tr>\r\n                </thead>\r\n                <tbody>\r\n                  @for (assessment of patientAssessments; track trackByAssessmentId($index, assessment)) {\r\n                    <tr>\r\n                      <td>{{ formatDate(assessment.updatedAt) || formatDate(assessment.createdAt) }}</td>\r\n                      <td>\r\n                        <span class=\"badge\" [class]=\"getStatusBadgeClass(assessment.status)\">\r\n                          {{ assessment.status }}\r\n                        </span>\r\n                      </td>\r\n                      <td>{{ assessment.version }}</td>\r\n                      <td>{{ assessment.totalScore !== null && assessment.totalScore !== undefined ? (assessment.totalScore | ceilValue) : '-' }}</td>\r\n                      <td>{{ assessment.overallPercentDisability !== null && assessment.overallPercentDisability !== undefined ? (assessment.overallPercentDisability | ceilValue) + '%' : '-' }}</td>\r\n                      <td class=\"text-center\">\r\n                        <div class=\"btn-group btn-group-sm\" role=\"group\">\r\n                          <button class=\"btn btn-outline-primary\" type=\"button\" (click)=\"onViewPdf(assessment)\" title=\"Visualizza e Stampa PDF\">\r\n                            <i class=\"fas fa-eye me-1\"></i> Visualizza\r\n                          </button>\r\n                          <button class=\"btn btn-outline-success\" type=\"button\" (click)=\"onDownloadPdf(assessment)\" title=\"Scarica PDF\">\r\n                            <i class=\"fas fa-download me-1\"></i> Scarica\r\n                          </button>\r\n                        </div>\r\n                      </td>\r\n                    </tr>\r\n                  }\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n          }\r\n        </div>\r\n        <hr class=\"my-4\">\r\n      } @else if (!isLoadingAssessments) {\r\n        <div class=\"alert alert-info mb-4\">\r\n          <i class=\"fas fa-info-circle me-2\"></i>\r\n          Nessuna valutazione trovata per questo paziente.\r\n        </div>\r\n      }\r\n\r\n      <!-- New Assessment Section -->\r\n      <div class=\"text-center py-5\">\r\n        <i class=\"fas fa-clipboard-question fa-4x text-primary mb-3\"></i>\r\n        <h4>Questionario WHODAS 2.0</h4>\r\n        <p class=\"text-muted mb-4\">Avvia una nuova valutazione per questo paziente</p>\r\n        <button class=\"btn btn-primary btn-lg\" type=\"button\" (click)=\"onStartAssessment()\">\r\n          <i class=\"fas fa-play me-2\"></i> Inizia Valutazione\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n",
